const d = $json;
const text = (d.complaint_description || '').toLowerCase();

const categories = [
  { name: 'Internet and Wi-Fi', dept: 'IT Department', words: ['wifi', 'wi-fi', 'internet', 'network', 'router', 'lan', 'bandwidth', 'broadband', 'portal down', 'no connection', 'slow connection'] },
  { name: 'Cleanliness and hygiene', dept: 'Housekeeping Department', words: ['clean', 'dirty', 'garbage', 'trash', 'dustbin', 'hygiene', 'smell', 'stink', 'toilet', 'washroom', 'bathroom', 'sanitation', 'pest', 'cockroach', 'rat', 'mosquito', 'sweep'] },
  { name: 'Classroom and maintenance', dept: 'Maintenance Department', words: ['classroom', 'projector', 'fan', 'light', 'bulb', 'ac ', 'air conditioner', 'bench', 'desk', 'chair', 'whiteboard', 'board', 'leak', 'ceiling', 'broken', 'repair', 'plumbing', 'electric', 'power', 'door', 'window', 'lift', 'elevator', 'maintenance'] },
  { name: 'Hostel complaints', dept: 'Hostel Administration', words: ['hostel', 'warden', 'mess', 'room', 'roommate', 'dorm', 'curfew', 'laundry', 'bed', 'mattress', 'canteen food'] },
  { name: 'Administrative complaints', dept: 'Administration Office', words: ['fee', 'fees', 'scholarship', 'certificate', 'admission', 'exam', 'result', 'marksheet', 'id card', 'document', 'registration', 'office', 'staff behaviour', 'refund', 'attendance', 'transcript'] },
];

const deptByCategory = {
  'Hostel complaints': 'Hostel Administration',
  'Classroom and maintenance': 'Maintenance Department',
  'Internet and Wi-Fi': 'IT Department',
  'Cleanliness and hygiene': 'Housekeeping Department',
  'Administrative complaints': 'Administration Office',
};

// Score each category by keyword matches in the description
let best = null;
let bestScore = 0;
for (const c of categories) {
  const score = c.words.filter(w => text.includes(w)).length;
  if (score > bestScore) { best = c; bestScore = score; }
}

// Fallback: use the category the student selected
const selected = d.complaint_category;
const category = best ? best.name : (deptByCategory[selected] ? selected : 'Administrative complaints');
const department = deptByCategory[category];

// Priority
const high = ['urgent', 'emergency', 'danger', 'dangerous', 'unsafe', 'safety', 'fire', 'short circuit', 'sparking', 'electric shock', 'harass', 'ragging', 'threat', 'assault', 'medical', 'injury', 'injured', 'flood', 'gas leak', 'no water', 'no electricity', 'food poison', 'security', 'exam tomorrow', 'immediately', 'collapsed'];
const medium = ['not working', 'broken', 'leak', 'slow', 'down', 'delay', 'delayed', 'pending', 'dirty', 'overflow', 'smell', 'stink', 'several days', 'days', 'week', 'repeated', 'again', 'no internet', 'unavailable'];
let priority = 'Low';
if (high.some(w => text.includes(w))) priority = 'High';
else if (medium.some(w => text.includes(w))) priority = 'Medium';

// Unique complaint ID: CMP-YYYYMMDD-HHMMSS-XXXX
const now = new Date();
const pad = n => String(n).padStart(2, '0');
const stamp = now.getUTCFullYear() + pad(now.getUTCMonth() + 1) + pad(now.getUTCDate()) + '-' + pad(now.getUTCHours()) + pad(now.getUTCMinutes()) + pad(now.getUTCSeconds());
const rand = Math.random().toString(36).substring(2, 6).toUpperCase();

return {
  json: {
    ...d,
    complaint_id: 'CMP-' + stamp + '-' + rand,
    identified_category: category,
    assigned_department: department,
    priority,
    status: 'Submitted',
  },
};

parameters.text:
=Analyse this student complaint:

Student-selected category: {{ $('Analyse Complaint').item.json.complaint_category }}
Location: {{ $('Analyse Complaint').item.json.location }}
Complaint description: {{ $('Analyse Complaint').item.json.complaint_description }}

Identify the correct complaint category and department.

Choose priority as High, Medium or Low.

Return JSON with exactly these fields: category, assigned_department, priority, reason.

Only if the complaint describes a genuine safety risk (electrical sparks, fire, gas leak, flooding, structural damage, harassment, ragging, threats, medical emergency or other danger to people), assign High priority and start the reason with "IMMEDIATE HUMAN ATTENTION REQUIRED:". Ordinary issues such as Wi-Fi or internet problems, broken fans or lights, cleanliness, or administrative requests are NOT safety risks: never use that phrase for them, and assign Low or Medium priority (High only if it is clearly urgent, such as an exam happening within a day).

